def find_templates(mat,outmat,special):
 pts=[(r,c) for r,row in enumerate(mat) for c,x in enumerate(row) if x==special]
 matches=[]
 H,W=len(mat),len(mat[0]);
 for dr in range(-max(r for r,c in pts),H-min(r for r,c in pts)):
  for dc in range(-max(c for r,c in pts),W-min(c for r,c in pts)):
   mapped=[(r+dr,c+dc) for r,c in pts]
   if all(0<=r<H and 0<=c<W and mat[r][c]==0 for r,c in mapped):
    recol=sum(outmat[r][c]==special for r,c in mapped)
    matches.append((dr,dc,recol,len(pts)))
 return matches
