def variants(pts):
 # normalized point-set transformations in 8 symmetries
 trans=[]
 for flip in [False,True]:
  for k in range(4):
   arr=[]
   for r,c in pts:
    x,y=r,(-c if flip else c)
    for _ in range(k):x,y=y,-x
    arr.append((x,y))
   a=min(x for x,y in arr);b=min(y for x,y in arr)
   trans.append(frozenset((x-a,y-b) for x,y in arr))
 return set(trans)
def shape_matches(mat,special):
 pts0=[(r,c) for r,row in enumerate(mat) for c,x in enumerate(row) if x==special]
 pts=set(pts0); H,W=len(mat),len(mat[0]); allmatches=[]; union=set()
 for sh in variants(pts):
  h=max(r for r,c in sh)+1; w=max(c for r,c in sh)+1
  for i in range(H-h+1):
   for j in range(W-w+1):
    loc={(i+r,j+c) for r,c in sh}
    if all(mat[r][c]==0 for r,c in loc):
     allmatches.append((sh,i,j));union |= loc
 return allmatches,union
