def threshold_union(mat,pts, threshold, allow_rot=False):
 H,W=len(mat),len(mat[0]); shapes=variants(pts) if allow_rot else [frozenset((r-min(a for a,b in pts),c-min(b for a,b in pts)) for r,c in pts)]
 out=set();matches=[]
 for sh in shapes:
  h=max(r for r,c in sh)+1;w=max(c for r,c in sh)+1
  for i in range(H-h+1):
   for j in range(W-w+1):
    loc={(i+r,j+c) for r,c in sh}
    zeros={p for p in loc if mat[p[0]][p[1]]==0}
    if len(zeros)>=threshold:
     out|=zeros; matches.append((i,j,len(zeros)))
 return out,matches
